export const GlobalOratorsLogo: React.FC<GlobalOratorsLogoProps> = ({
  variant = 'mark',
  colorMode = 'gold',
  className = 'h-9 w-9',
  title = 'Global Orators Project'
}) => {
  // Unique gradient ID per component instance to avoid DOM collisions
  const gradId = React.useId().replace(/:/g, '');
  const goldGradId = `goGoldGrad_${gradId}`;
  const clipId = `goClip_${gradId}`;

  // Color resolution
  const fillSource = 
    colorMode === 'gold' 
      ? `url(#${goldGradId})` 
      : colorMode === 'theme' 
        ? 'var(--app-fg, #0D3A35)' 
        : 'currentColor';

  const strokeSource = fillSource;

  const gradientDefs = (
    <defs>
      <linearGradient id={goldGradId} x1="20%" y1="0%" x2="80%" y2="100%">
        <stop offset="0%" stopColor="#FDEBB2" />
        <stop offset="25%" stopColor="#E3B95C" />
        <stop offset="50%" stopColor="#C89630" />
        <stop offset="75%" stopColor="#E9CA76" />
        <stop offset="90%" stopColor="#A3731B" />
        <stop offset="100%" stopColor="#7D530F" />
      </linearGradient>
      <clipPath id={clipId}>
        <circle cx="592.2" cy="444.6" r="169.5" />
      </clipPath>
    </defs>
  );

  if (variant === 'full') {
    return (
      <svg
        viewBox="90 220 1080 820"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        className={`shrink-0 transition-transform duration-300 ${className}`}
        role="img"
        aria-label={title}
      >
        <title>{title}</title>
        {gradientDefs}
        <g id="go-mark">
          <circle
            cx="592.2"
            cy="444.6"
            r="171.0"
            fill="none"
            stroke={strokeSource}
            strokeWidth="2.8"
            data-testid="go-globe-rim"
          />
          <path
            clipPath={`url(#${clipId})`}
            fill={fillSource}
            fillRule="evenodd"
            d={CONTINENTS_PATH}
          />
          <path fill={fillSource} d={CRESCENT_PATH} />
        </g>
        <path
          id="go-typography"
          fill={fillSource}
          fillRule="evenodd"
          d={TYPOGRAPHY_PATH}
        />
      </svg>
    );
  }

  if (variant === 'horizontal') {
    return (
      <div className={`flex items-center gap-2.5 shrink-0 ${className}`}>
        <svg
          viewBox="400 215 460 460"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          className="h-full w-auto aspect-square shrink-0"
          role="img"
          aria-label={title}
        >
          <title>{title}</title>
          {gradientDefs}
          <g id="go-mark">
            <circle
              cx="592.2"
              cy="444.6"
              r="171.0"
              fill="none"
              stroke={strokeSource}
              strokeWidth="2.8"
            data-testid="go-globe-rim"
            />
            <path
              clipPath={`url(#${clipId})`}
              fill={fillSource}
              fillRule="evenodd"
              d={CONTINENTS_PATH}
            />
            <path fill={fillSource} d={CRESCENT_PATH} />
          </g>
        </svg>
        <div className="flex flex-col justify-center text-left leading-none">
          <span className="text-[9px] font-mono tracking-widest uppercase text-slate-400 opacity-80 mb-0.5">
            The
          </span>
          <span className="font-serif font-black text-sm sm:text-base tracking-tight text-slate-100 dark:text-slate-100">
            GLOBAL <span className="text-[#C89630] dark:text-[#E3B95C]">ORATORS</span>
          </span>
          <span className="text-[8px] font-mono tracking-widest uppercase text-slate-400 opacity-70 mt-0.5">
            Project
          </span>
        </div>
      </div>
    );
  }

  // Default: 'mark'
  return (
    <svg
      viewBox="400 215 460 460"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={`shrink-0 transition-transform duration-300 ${className}`}
      role="img"
      aria-label={title}
    >
      <title>{title}</title>
      {gradientDefs}
      <g id="go-mark">
        <circle
          cx="592.2"
          cy="444.6"
          r="171.0"
          fill="none"
          stroke={strokeSource}
          strokeWidth="2.8"
            data-testid="go-globe-rim"
        />
        <path
          clipPath={`url(#${clipId})`}
          fill={fillSource}
          fillRule="evenodd"
          d={CONTINENTS_PATH}
        />
        <path fill={fillSource} d={CRESCENT_PATH} />
      </g>
    </svg>
  );
};

export const NubianFitLogo = GlobalOratorsLogo;

export default GlobalOratorsLogo;
